-- Distribuição física da LOB. Sem escrita no cronograma, baseline ou EAP.
CREATE TABLE IF NOT EXISTS "lob_activity_locations" (
  "id" integer PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY,
  "projectId" integer NOT NULL REFERENCES "projects"("id"),
  "versionId" integer NOT NULL REFERENCES "project_plan_versions"("id"),
  "activityId" integer NOT NULL REFERENCES "schedule_activities"("id"),
  "unitId" integer NOT NULL REFERENCES "production_units"("id"),
  "plannedQuantity" numeric(18,3) NOT NULL,
  "startDate" varchar(10) NOT NULL,
  "finishDate" varchar(10) NOT NULL,
  "createdAt" timestamp with time zone NOT NULL DEFAULT now(),
  "updatedAt" timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "lob_locations_quantity_positive" CHECK ("plannedQuantity" > 0),
  CONSTRAINT "lob_locations_dates_ordered" CHECK ("startDate" <= "finishDate"),
  CONSTRAINT "lob_locations_date_format" CHECK (
    "startDate" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$'
    AND "finishDate" ~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$')
);
--> statement-breakpoint
CREATE UNIQUE INDEX IF NOT EXISTS "lob_activity_locations_unique_idx"
  ON "lob_activity_locations"("activityId","unitId");
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "lob_activity_locations_project_version_idx"
  ON "lob_activity_locations"("projectId","versionId");
--> statement-breakpoint
CREATE INDEX IF NOT EXISTS "lob_activity_locations_unit_idx"
  ON "lob_activity_locations"("unitId");
--> statement-breakpoint
ALTER TABLE "lob_activity_locations" ENABLE ROW LEVEL SECURITY;
--> statement-breakpoint
-- O backend usa o papel SQL arquimedes_app; nenhum cliente anon/authenticated
-- acessa parcelas diretamente pela Data API (RLS sem políticas para eles).
REVOKE ALL ON TABLE public."lob_activity_locations" FROM anon,authenticated,PUBLIC;
--> statement-breakpoint
REVOKE ALL ON SEQUENCE public."lob_activity_locations_id_seq" FROM anon,authenticated,PUBLIC;
--> statement-breakpoint
GRANT SELECT,INSERT,UPDATE,DELETE ON TABLE public."lob_activity_locations" TO arquimedes_app;
--> statement-breakpoint
GRANT USAGE,SELECT ON SEQUENCE public."lob_activity_locations_id_seq" TO arquimedes_app;
--> statement-breakpoint
DROP POLICY IF EXISTS "lob_backend_guard" ON public."lob_activity_locations";
--> statement-breakpoint
CREATE POLICY "lob_backend_guard" ON public."lob_activity_locations"
  FOR ALL TO arquimedes_app USING (true) WITH CHECK (true);
